import crypto from "node:crypto";
import { prisma, executeDdlBatch } from "@/lib/prisma";
import { logActivity } from "@/lib/activity-logger";
import { toInr, type CurrencyRates } from "@/lib/pricing/currency";
import { getCurrencyRates } from "@/lib/pricing/db";

export const MARKETPLACE_PLATFORMS = ["EBAY", "ETSY", "AMAZON"] as const;
export const ACTIVE_LISTING_STATUSES = ["ACTIVE", "LISTED"] as const;
export const MARKETPLACE_EVENT_MODULE = "MARKETPLACE";

/**
 * Single source of truth for "which rows are marketplace listings".
 *
 * Every marketplace metric must be derived from the rows that appear on
 * Marketplaces -> Listings, i.e. `Listing.marketplaceShopId IS NOT NULL`.
 * Rows with a NULL shop are the legacy "Catalog Listing Tools" entries and
 * must never be counted anywhere in the marketplace dashboards.
 *
 * The fragment expects `l` to be the alias of the `Listing` table.
 */
export const MARKETPLACE_LISTING_SCOPE_SQL = `l."marketplaceShopId" IS NOT NULL AND UPPER(l."status") IN ('ACTIVE', 'LISTED')`;

/**
 * Joins `Listing` (aliased `l`) to its ERP `Inventory` row (aliased `i`).
 *
 * Listings synced before the product link was persisted can still carry only
 * `listingSku`, so an exact SKU match is used as a fallback. `Inventory.sku`
 * is unique, therefore this join can never fan out into duplicate rows.
 */
export function marketplaceInventoryJoinSql(kind: "INNER" | "LEFT" = "INNER"): string {
  return `${kind} JOIN "Inventory" i ON (
    i."id" = l."inventoryId"
    OR (
      l."inventoryId" IS NULL
      AND l."listingSku" IS NOT NULL
      AND UPPER(TRIM(l."listingSku")) = UPPER(TRIM(i."sku"))
    )
  )`;
}

export type MarketplacePlatform = (typeof MARKETPLACE_PLATFORMS)[number];
export type MarketplaceConflictStatus = "Pending" | "Reviewed" | "Resolved";

export type MarketplaceConflictRow = {
  id: string;
  inventoryId: string;
  sku: string;
  productName: string;
  soldDate: string | null;
  currentQuantity: number;
  activePlatforms: string;
  conflictStatus: MarketplaceConflictStatus;
  createdAt: string;
  updatedAt: string;
  resolvedAt: string | null;
  resolvedBy: string | null;
  resolutionNote: string | null;
};

export type MarketplaceTimelineRow = {
  id: string;
  actionType: string;
  userName: string | null;
  source: string | null;
  details: string | null;
  entityIdentifier: string | null;
  createdAt: Date;
};

export type MarketplacePortfolioRow = {
  inventoryId: string;
  sku: string;
  productName: string;
  category: string | null;
  inventoryStatus: string;
  pieces: number;
  createdAt: string;
  platforms: MarketplacePlatform[];
  urls: Partial<Record<MarketplacePlatform, string[]>>;
  lastListedDates: Partial<Record<MarketplacePlatform, string>>;
  coveragePercent: number;
  missingPlatforms: MarketplacePlatform[];
  opportunityScore: number;
  readyToList: boolean;
  hasImage: boolean;
  hasCertificate: boolean;
  // Pricing fields (used by the pricing analysis view)
  costPrice: number | null;
  sellingPrice: number | null;
  purchaseRatePerCarat: number | null;
  flatPurchaseCost: number | null;
  weightValue: number | null;
  weightUnit: string | null;
  marketplacePrices: Partial<Record<MarketplacePlatform, number>>;
  marketplaceCurrencies: Partial<Record<MarketplacePlatform, string>>;
  // URLs are optional marketplace metadata; counts must not depend on them.
  listingCounts: Partial<Record<MarketplacePlatform, number>>;
  /** Connected shop ids that already have an active listing for this SKU. */
  listedShopIds: string[];
  /** Connected shops where this SKU can still be listed. */
  missingShops: Array<{ id: string; marketplace: MarketplacePlatform; name: string }>;
};

export type MarketplaceDashboardData = {
  totalListings: number;
  platformCounts: Record<MarketplacePlatform, number>;
  conflictCounts: Record<MarketplaceConflictStatus, number>;
  criticalConflicts: number;
  coverageSummary: Record<string, number>;
  recentActivity: MarketplaceTimelineRow[];
  rows: MarketplacePortfolioRow[];
};

export function normalizePlatform(value: string | null | undefined): MarketplacePlatform | null {
  const normalized = String(value || "").trim().toUpperCase();
  if ((MARKETPLACE_PLATFORMS as readonly string[]).includes(normalized)) return normalized as MarketplacePlatform;
  return null;
}

function toIsoDate(value: unknown): string {
  if (!value) return "";
  const d = new Date(value as string | number | Date);
  return Number.isNaN(d.getTime()) ? "" : d.toISOString();
}

function parsePlatforms(value: string | null | undefined): string[] {
  if (!value) return [];
  try {
    const parsed = JSON.parse(value);
    return Array.isArray(parsed) ? parsed.filter(Boolean).map(String) : [];
  } catch {
    return [];
  }
}

let ensuringMccSchema = false;
let ensuredMccSchema = false;
let ensureMccSchemaPromise: Promise<void> | null = null;

export async function ensureMarketplaceControlCenterSchema(): Promise<void> {
  if (ensuredMccSchema) return;
  if (ensuringMccSchema && ensureMccSchemaPromise) return ensureMccSchemaPromise;
  ensuringMccSchema = true;
  ensureMccSchemaPromise = (async () => {
    try {
      await executeDdlBatch([
        `CREATE TABLE IF NOT EXISTS "MarketplaceConflict" (
          "id" TEXT NOT NULL PRIMARY KEY,
          "inventoryId" TEXT NOT NULL,
          "sku" TEXT NOT NULL,
          "productName" TEXT NOT NULL,
          "soldDate" DATETIME,
          "currentQuantity" INTEGER NOT NULL DEFAULT 0,
          "activePlatforms" TEXT NOT NULL DEFAULT '[]',
          "conflictStatus" TEXT NOT NULL DEFAULT 'Pending',
          "resolvedAt" DATETIME,
          "resolvedBy" TEXT,
          "resolutionNote" TEXT,
          "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
          "updatedAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
        );`,
        `CREATE INDEX IF NOT EXISTS "MarketplaceConflict_inventoryId_idx" ON "MarketplaceConflict"("inventoryId");`,
        `CREATE INDEX IF NOT EXISTS "MarketplaceConflict_sku_idx" ON "MarketplaceConflict"("sku");`,
        `CREATE INDEX IF NOT EXISTS "MarketplaceConflict_status_idx" ON "MarketplaceConflict"("conflictStatus");`,
        `CREATE INDEX IF NOT EXISTS "MarketplaceConflict_createdAt_idx" ON "MarketplaceConflict"("createdAt");`,
        `CREATE INDEX IF NOT EXISTS "MarketplaceConflict_inventory_status_idx" ON "MarketplaceConflict"("inventoryId", "conflictStatus");`,
        `CREATE INDEX IF NOT EXISTS "Listing_inventoryId_status_idx" ON "Listing"("inventoryId", "status");`,
        `CREATE INDEX IF NOT EXISTS "Listing_platform_status_idx" ON "Listing"("platform", "status");`,
        `CREATE INDEX IF NOT EXISTS "Listing_inventory_platform_idx" ON "Listing"("inventoryId", "platform");`,
        `CREATE INDEX IF NOT EXISTS "ActivityLog_entityId_idx" ON "ActivityLog"("entityId");`,
        `CREATE INDEX IF NOT EXISTS "ActivityLog_actionType_idx" ON "ActivityLog"("actionType");`,
      ]);
    } catch {
      // Idempotent by design; swallow so safe deploys never break.
    } finally {
      ensuredMccSchema = true;
      ensuringMccSchema = false;
      ensureMccSchemaPromise = null;
    }
  })();
  return ensureMccSchemaPromise;
}

export async function logMarketplaceActivity(params: {
  entityType: string;
  entityId: string;
  entityIdentifier: string;
  actionType: string;
  details: string;
  userId?: string;
  userName?: string;
  source?: string;
  metadata?: Record<string, unknown>;
}) {
  await logActivity({
    module: MARKETPLACE_EVENT_MODULE,
    entityType: params.entityType,
    entityId: params.entityId,
    entityIdentifier: params.entityIdentifier,
    actionType: params.actionType,
    description: params.details,
    details: params.details,
    metadata: params.metadata,
    userId: params.userId,
    userName: params.userName,
    source: params.source || "SYSTEM",
  });
}

async function getActiveListingsForInventory(inventoryId: string) {
  const rows = await prisma.$queryRawUnsafe<Array<{
    platform: string | null;
    listingUrl: string | null;
  }>>(
    `SELECT "platform", "listingUrl" FROM "Listing" WHERE "inventoryId" = ? AND UPPER("status") IN ('ACTIVE', 'LISTED') ORDER BY "createdAt" DESC`,
    inventoryId
  );

  return rows
    .map((row) => ({ platform: normalizePlatform(row.platform), listingUrl: row.listingUrl || null }))
    .filter((row): row is { platform: MarketplacePlatform; listingUrl: string | null } => Boolean(row.platform));
}

export async function triggerMarketplaceConflict(params: {
  inventoryId: string;
  status?: string | null;
  pieces?: number | null;
  userId?: string;
  userName?: string;
  source?: string;
}) {
  await ensureMarketplaceControlCenterSchema();

  const inventory = await prisma.inventory.findUnique({
    where: { id: params.inventoryId },
    select: { id: true, sku: true, itemName: true, status: true, pieces: true },
  });
  if (!inventory) return { created: false, conflict: null };

  const currentStatus = String(params.status || inventory.status || "").toUpperCase();
  const currentPieces = typeof params.pieces === "number" ? params.pieces : (inventory.pieces ?? 0);
  const shouldCheck = currentStatus === "SOLD" || currentStatus === "INACTIVE" || currentPieces === 0;
  if (!shouldCheck) return { created: false, conflict: null };

  const activeListings = await getActiveListingsForInventory(inventory.id);
  if (activeListings.length === 0) return { created: false, conflict: null };

  const activePlatforms = activeListings.map((row) => row.platform);
  const existing = await prisma.$queryRawUnsafe<Array<MarketplaceConflictRow>>(
    `SELECT * FROM "MarketplaceConflict" WHERE "inventoryId" = ? AND "conflictStatus" IN ('Pending', 'Reviewed') ORDER BY "createdAt" DESC LIMIT 1`,
    inventory.id
  );

  const payload = {
    inventoryId: inventory.id,
    sku: inventory.sku,
    productName: inventory.itemName,
    soldDate: new Date().toISOString(),
    currentQuantity: currentPieces,
    activePlatforms: JSON.stringify(activePlatforms),
    conflictStatus: "Pending" as MarketplaceConflictStatus,
  };

  if (existing.length > 0) {
    await prisma.$executeRawUnsafe(
      `UPDATE "MarketplaceConflict" SET "sku" = ?, "productName" = ?, "soldDate" = ?, "currentQuantity" = ?, "activePlatforms" = ?, "conflictStatus" = 'Pending', "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = ?`,
      payload.sku,
      payload.productName,
      payload.soldDate,
      payload.currentQuantity,
      payload.activePlatforms,
      existing[0].id
    );

    await logMarketplaceActivity({
      entityType: "Inventory",
      entityId: inventory.id,
      entityIdentifier: inventory.sku,
      actionType: "CONFLICT_UPDATED",
      details: `Marketplace conflict updated for ${inventory.sku}`,
      userId: params.userId,
      userName: params.userName,
      source: params.source || "SYSTEM",
      metadata: { activePlatforms },
    });

    return { created: false, conflict: { ...existing[0], ...payload } };
  }

  const conflictId = crypto.randomUUID();
  await prisma.$executeRawUnsafe(
    `INSERT INTO "MarketplaceConflict" ("id", "inventoryId", "sku", "productName", "soldDate", "currentQuantity", "activePlatforms", "conflictStatus", "createdAt", "updatedAt") VALUES (?, ?, ?, ?, ?, ?, ?, 'Pending', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)`,
    conflictId,
    payload.inventoryId,
    payload.sku,
    payload.productName,
    payload.soldDate,
    payload.currentQuantity,
    payload.activePlatforms
  );

  await logMarketplaceActivity({
    entityType: "Inventory",
    entityId: inventory.id,
    entityIdentifier: inventory.sku,
    actionType: "CONFLICT_CREATED",
    details: `Marketplace conflict created for ${inventory.sku}`,
    userId: params.userId,
    userName: params.userName,
    source: params.source || "SYSTEM",
    metadata: { activePlatforms },
  });

  return { created: true, conflict: { id: conflictId, ...payload } };
}

export async function resolveMarketplaceConflict(params: {
  conflictId: string;
  userId?: string;
  userName?: string;
  note?: string;
}) {
  await ensureMarketplaceControlCenterSchema();

  const conflict = await prisma.$queryRawUnsafe<Array<MarketplaceConflictRow>>(
    `SELECT * FROM "MarketplaceConflict" WHERE "id" = ? LIMIT 1`,
    params.conflictId
  );
  if (conflict.length === 0) return { success: false, message: "Conflict not found" };

  await prisma.$executeRawUnsafe(
    `UPDATE "MarketplaceConflict" SET "conflictStatus" = 'Resolved', "resolvedAt" = CURRENT_TIMESTAMP, "resolvedBy" = ?, "resolutionNote" = ?, "updatedAt" = CURRENT_TIMESTAMP WHERE "id" = ?`,
    params.userName || params.userId || "System",
    params.note || null,
    params.conflictId
  );

  await logMarketplaceActivity({
    entityType: "Inventory",
    entityId: conflict[0].inventoryId,
    entityIdentifier: conflict[0].sku,
    actionType: "CONFLICT_RESOLVED",
    details: `Marketplace conflict resolved for ${conflict[0].sku}`,
    userId: params.userId,
    userName: params.userName,
    source: "WEB",
    metadata: { conflictId: params.conflictId, note: params.note || null },
  });

  return { success: true };
}

export async function getMarketplaceConflictRows(options: {
  status?: string;
  sku?: string;
  page?: number;
  limit?: number;
} = {}) {
  await ensureMarketplaceControlCenterSchema();
  const page = Math.max(Number(options.page || 1), 1);
  const limit = Math.min(Math.max(Number(options.limit || 50), 1), 200);
  const skip = (page - 1) * limit;

  const conditions: string[] = [];
  const values: Array<string | number> = [];
  if (options.status && options.status !== "ALL") {
    conditions.push(`"conflictStatus" = ?`);
    values.push(options.status);
  }
  if (options.sku) {
    conditions.push(`("sku" LIKE ? OR "productName" LIKE ?)`);
    values.push(`%${options.sku}%`, `%${options.sku}%`);
  }

  const whereSql = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
  const rows = await prisma.$queryRawUnsafe<Array<MarketplaceConflictRow>>(
    `SELECT * FROM "MarketplaceConflict" ${whereSql} ORDER BY "createdAt" DESC LIMIT ${limit} OFFSET ${skip}`,
    ...values
  );
  const countRows = await prisma.$queryRawUnsafe<Array<{ total: number }>>(
    `SELECT COUNT(*) AS total FROM "MarketplaceConflict" ${whereSql}`,
    ...values
  );

  return { rows, total: Number(countRows[0]?.total || 0), page, limit };
}

export async function getMarketplaceConflictListingMap(inventoryIds: string[]) {
  await ensureMarketplaceControlCenterSchema();
  if (inventoryIds.length === 0) return new Map<string, Record<MarketplacePlatform, string[]>>();

  const placeholders = inventoryIds.map(() => "?").join(", ");
  const rows = await prisma.$queryRawUnsafe<Array<{ inventoryId: string; platform: string | null; listingUrl: string | null }>>(
    `SELECT "inventoryId", "platform", "listingUrl" FROM "Listing" WHERE "inventoryId" IN (${placeholders}) AND UPPER("status") IN ('ACTIVE', 'LISTED') ORDER BY "createdAt" DESC`,
    ...inventoryIds
  );

  const map = new Map<string, Record<MarketplacePlatform, string[]>>();
  for (const row of rows) {
    const platform = normalizePlatform(row.platform);
    if (!platform) continue;
    if (!map.has(row.inventoryId)) map.set(row.inventoryId, { EBAY: [], ETSY: [], AMAZON: [] });
    if (row.listingUrl) map.get(row.inventoryId)![platform].push(row.listingUrl);
  }
  return map;
}

export async function getMarketplaceTimeline(entityId?: string, limit = 12) {
  await ensureMarketplaceControlCenterSchema();
  const rows = entityId
    ? await prisma.activityLog.findMany({
        where: { entityId, module: MARKETPLACE_EVENT_MODULE },
        orderBy: { createdAt: "desc" },
        take: limit,
      })
    : await prisma.activityLog.findMany({
        where: {
          module: MARKETPLACE_EVENT_MODULE,
          // Queueing jobs and connection changes belong in Sync History / the
          // Connections page, not in the marketplace business timeline.
          actionType: { notIn: ["SYNC_QUEUED", "SYNC_STARTED", "SYNC_COMPLETED", "SHOP_CONNECTED", "SHOP_DISCONNECTED"] },
        },
        orderBy: { createdAt: "desc" },
        take: limit,
      });

  return rows.map((row) => ({
    id: row.id,
    actionType: row.actionType || row.action || "UNKNOWN",
    userName: row.userName,
    source: row.source,
    details: row.description || row.details,
    entityIdentifier: row.entityIdentifier,
    createdAt: row.createdAt,
  })) as MarketplaceTimelineRow[];
}

/** Human readable marketplace name for dashboard labels and activity text. */
export function platformDisplay(raw: string | null | undefined): string {
  const key = String(raw || "").toUpperCase();
  return key === "EBAY" ? "eBay" : key === "ETSY" ? "Etsy" : key === "AMAZON" ? "Amazon" : String(raw || "-");
}

/**
 * Activity of the legacy "Catalog Listing Tools" surface. Those events belong
 * to the old /listings page and must not appear on marketplace dashboards
 * unless the event actually references a live marketplace listing.
 */
const LEGACY_LISTING_TOOL_ACTIONS = new Set(["LISTING_LINKED", "LISTING_UPDATED", "LISTING_REMOVED"]);

function listingIdFromMetadata(raw: string | null | undefined): string | null {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as { listingId?: unknown };
    return typeof parsed?.listingId === "string" && parsed.listingId ? parsed.listingId : null;
  } catch {
    return null;
  }
}

/**
 * Recent activity that belongs to Marketplaces -> Listings: marketplace
 * conflicts, connection/sync milestones, and listing events that reference a
 * live marketplace listing. Legacy catalog listing churn is filtered out, and
 * listing sync jobs are merged in so the feed always reflects what the
 * listings page actually did last.
 */
export async function getMarketplaceActivityFeed(limit = 10): Promise<MarketplaceTimelineRow[]> {
  await ensureMarketplaceControlCenterSchema();

  const [activityRows, marketplaceListingRows, syncJobs] = await Promise.all([
    prisma.activityLog.findMany({
      where: {
        module: MARKETPLACE_EVENT_MODULE,
        actionType: { notIn: ["SYNC_QUEUED", "SYNC_STARTED", "SYNC_COMPLETED", "SHOP_CONNECTED", "SHOP_DISCONNECTED"] },
      },
      orderBy: { createdAt: "desc" },
      take: 250,
    }),
    prisma.listing.findMany({
      where: { marketplaceShopId: { not: null } },
      select: { id: true },
    }),
    prisma.marketplaceSyncJob.findMany({
      orderBy: { updatedAt: "desc" },
      take: 25,
      include: { marketplaceShop: { select: { marketplace: true, name: true } } },
    }),
  ]);

  const marketplaceListingIds = new Set(marketplaceListingRows.map((row) => row.id));
  const activity: MarketplaceTimelineRow[] = [];

  for (const row of activityRows) {
    if (LEGACY_LISTING_TOOL_ACTIONS.has(row.actionType || "")) {
      const listingId = listingIdFromMetadata(row.metadata);
      if (!listingId || !marketplaceListingIds.has(listingId)) continue;
    }
    activity.push({
      id: row.id,
      actionType: row.actionType || row.action || "UNKNOWN",
      userName: row.userName,
      source: row.source,
      details: row.description || row.details,
      entityIdentifier: row.entityIdentifier,
      createdAt: row.createdAt,
    });
  }

  // One entry per sync type + status + shop so a burst of identical jobs does
  // not flood the feed; the newest run of each kind wins.
  const seenSyncKeys = new Set<string>();
  for (const job of syncJobs) {
    const key = `${job.syncType}|${job.status}|${job.marketplaceShopId}`;
    if (seenSyncKeys.has(key)) continue;
    seenSyncKeys.add(key);
    activity.push({
      id: job.id,
      actionType: `SYNC_${job.status}`,
      userName: job.requestedBy || "System",
      source: "SYNC",
      details: `${job.syncType} sync ${job.status.toLowerCase()} · ${platformDisplay(job.marketplaceShop.marketplace)} · ${job.marketplaceShop.name}`,
      entityIdentifier: job.marketplaceShop.name,
      createdAt: job.endedAt || job.updatedAt,
    });
  }

  activity.sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime());
  return activity.slice(0, limit);
}

export async function getMarketplaceDashboardData(options: {
  category?: string;
  marketplace?: string;
  from?: string;
  to?: string;
} = {}): Promise<MarketplaceDashboardData> {
  await ensureMarketplaceControlCenterSchema();

  const rows = await prisma.$queryRawUnsafe<Array<{
    inventoryId: string;
    sku: string;
    itemName: string;
    category: string | null;
    inventoryStatus: string;
    pieces: number | null;
    createdAt: string;
    platform: string | null;
    listingUrl: string | null;
    lastListedDate: string | null;
    costPrice: number | null;
    sellingPrice: number | null;
    purchaseRatePerCarat: number | null;
    flatPurchaseCost: number | null;
    weightValue: number | null;
    weightUnit: string | null;
    listedPrice: number | null;
    currency: string | null;
    marketplaceShopId: string | null;
  }>>(
    `SELECT i."id" AS "inventoryId", i."sku", i."itemName", i."category", i."status" AS "inventoryStatus", i."pieces", i."createdAt",
            i."costPrice", i."sellingPrice", i."purchaseRatePerCarat", i."flatPurchaseCost", i."weightValue", i."weightUnit",
            l."platform", l."listingUrl", l."createdAt" AS "lastListedDate", l."listedPrice", l."currency", l."marketplaceShopId"
     FROM "Inventory" i
     LEFT JOIN "Listing" l ON (l."inventoryId" = i."id" OR (l."inventoryId" IS NULL AND l."listingSku" IS NOT NULL AND UPPER(TRIM(l."listingSku")) = UPPER(TRIM(i."sku"))))
       AND ${MARKETPLACE_LISTING_SCOPE_SQL}
     WHERE i."status" != 'SOLD'
     ORDER BY i."sku" ASC, l."platform" ASC, l."createdAt" DESC`
  );

  const grouped = new Map<string, MarketplacePortfolioRow>();
  for (const row of rows) {
    const existing = grouped.get(row.inventoryId) || {
      inventoryId: row.inventoryId,
      sku: row.sku,
      productName: row.itemName,
      category: row.category,
      inventoryStatus: row.inventoryStatus,
      pieces: Number(row.pieces || 0),
      createdAt: toIsoDate(row.createdAt),
      platforms: [] as MarketplacePlatform[],
      urls: { EBAY: [], ETSY: [], AMAZON: [] } as Record<MarketplacePlatform, string[]>,
      lastListedDates: {} as Partial<Record<MarketplacePlatform, string>>,
      coveragePercent: 0,
      missingPlatforms: [] as MarketplacePlatform[],
      opportunityScore: 3,
      readyToList: false,
      hasImage: false,
      hasCertificate: false,
      costPrice: row.costPrice == null ? null : Number(row.costPrice),
      sellingPrice: row.sellingPrice == null ? null : Number(row.sellingPrice),
      purchaseRatePerCarat: row.purchaseRatePerCarat == null ? null : Number(row.purchaseRatePerCarat),
      flatPurchaseCost: row.flatPurchaseCost == null ? null : Number(row.flatPurchaseCost),
      weightValue: row.weightValue == null ? null : Number(row.weightValue),
      weightUnit: row.weightUnit || null,
      marketplacePrices: {} as Partial<Record<MarketplacePlatform, number>>,
      marketplaceCurrencies: {} as Partial<Record<MarketplacePlatform, string>>,
      listingCounts: {} as Partial<Record<MarketplacePlatform, number>>,
      listedShopIds: [],
      missingShops: [],
    };

    const platform = normalizePlatform(row.platform);
    if (platform) {
      if (!existing.platforms.includes(platform)) existing.platforms.push(platform);
      existing.listingCounts[platform] = (existing.listingCounts[platform] || 0) + 1;
      if (row.listingUrl) existing.urls[platform] = [...(existing.urls[platform] || []), row.listingUrl];
      // First encounter holds the latest listedDate / price due to ORDER BY l."createdAt" DESC
      if (row.lastListedDate && !existing.lastListedDates[platform]) {
        existing.lastListedDates[platform] = toIsoDate(row.lastListedDate);
      }
      if (row.listedPrice != null && existing.marketplacePrices[platform] == null) {
        existing.marketplacePrices[platform] = Number(row.listedPrice);
        existing.marketplaceCurrencies[platform] = row.currency || "USD";
      }
      if (row.marketplaceShopId && !existing.listedShopIds.includes(row.marketplaceShopId)) {
        existing.listedShopIds.push(row.marketplaceShopId);
      }
    }

    grouped.set(row.inventoryId, existing);
  }

  const filtered = [...grouped.values()].filter((item) => {
    if (options.category && options.category !== "ALL" && item.category !== options.category) return false;
    if (options.marketplace && options.marketplace !== "ALL") {
      const marketplace = normalizePlatform(options.marketplace);
      if (!marketplace || !item.platforms.includes(marketplace)) return false;
    }
    if (options.from) {
      const from = new Date(`${options.from}T00:00:00.000Z`);
      if (!Number.isNaN(from.getTime()) && new Date(item.createdAt) < from) return false;
    }
    if (options.to) {
      const to = new Date(`${options.to}T23:59:59.999Z`);
      if (!Number.isNaN(to.getTime()) && new Date(item.createdAt) > to) return false;
    }
    return true;
  });

  // Listing coverage must be evaluated per connected shop, not merely per
  // platform. Two Etsy shops are separate sales channels and each must get a
  // separate actionable queue.
  const connectedShops = await prisma.marketplaceShop.findMany({
    where: { status: "CONNECTED", connection: { status: "CONNECTED" } },
    select: { id: true, marketplace: true, name: true },
    orderBy: [{ marketplace: "asc" }, { name: "asc" }],
  });
  const actionableShops = connectedShops.flatMap((shop) => {
    const marketplace = normalizePlatform(shop.marketplace);
    return marketplace ? [{ id: shop.id, marketplace, name: shop.name }] : [];
  });

  // Always validate listing readiness. The previous implementation validated
  // only zero-listing products, allowing partially listed incomplete records
  // into the opportunity queue.
  const inventoryChecks = filtered.length
    ? await prisma.inventory.findMany({
        where: { id: { in: filtered.map((item) => item.inventoryId) } },
        select: {
          id: true,
          imageUrl: true,
          certificateNo: true,
          certificateNumber: true,
          description: true,
          hsnCode: true,
          media: { where: { type: "IMAGE" }, select: { id: true }, take: 1 },
        },
      })
    : [];
  const checkMap = new Map(inventoryChecks.map((item) => [item.id, item]));

  for (const item of filtered) {
    const activeSet = new Set(item.platforms);
    item.coveragePercent = actionableShops.length
      ? Math.round((item.listedShopIds.filter((id) => actionableShops.some((shop) => shop.id === id)).length / actionableShops.length) * 100)
      : 0;
    item.missingPlatforms = MARKETPLACE_PLATFORMS.filter((platform) => !activeSet.has(platform));
    item.missingShops = actionableShops.filter((shop) => !item.listedShopIds.includes(shop.id));
    item.opportunityScore = item.missingShops.length;
    item.platforms.sort();
    const check = checkMap.get(item.inventoryId);
    item.hasImage = Boolean(check?.imageUrl?.trim()) || Boolean(check?.media.length);
    item.hasCertificate = Boolean(check?.certificateNo?.trim()) || Boolean(check?.certificateNumber?.trim());
    const status = item.inventoryStatus.trim().toUpperCase();
    const hasSaleableStock = item.pieces > 0 && !["SOLD", "INACTIVE", "OUT_OF_STOCK", "SOLD_OUT"].includes(status);
    const hasRequiredDescription = Boolean(check?.description?.trim());
    const hasHsnCode = Boolean(check?.hsnCode?.trim());
    item.readyToList = hasSaleableStock && item.hasImage && item.hasCertificate && hasRequiredDescription && hasHsnCode;
  }

  // Active listing totals come straight from the Marketplace -> Listings rows
  // (not from the inventory portfolio), so the widget always matches that page.
  const listingScopeRows = await prisma.$queryRawUnsafe<Array<{ platform: string | null; total: number }>>(
    `SELECT "platform", COUNT(*) AS total FROM "Listing"
     WHERE "marketplaceShopId" IS NOT NULL AND UPPER("status") IN ('ACTIVE', 'LISTED')
     GROUP BY "platform"`
  );
  const platformCounts = MARKETPLACE_PLATFORMS.reduce((acc, platform) => {
    acc[platform] = 0;
    return acc;
  }, {} as Record<MarketplacePlatform, number>);
  for (const row of listingScopeRows) {
    const platform = normalizePlatform(row.platform);
    if (platform) platformCounts[platform] += Number(row.total || 0);
  }
  const totalListings = platformCounts.EBAY + platformCounts.ETSY + platformCounts.AMAZON;

  const conflictRows = await prisma.$queryRawUnsafe<Array<{ conflictStatus: string; total: number }>>(
    `SELECT "conflictStatus", COUNT(*) AS total FROM "MarketplaceConflict" GROUP BY "conflictStatus"`
  );
  const conflictCounts: Record<MarketplaceConflictStatus, number> = { Pending: 0, Reviewed: 0, Resolved: 0 };
  for (const row of conflictRows) {
    if (row.conflictStatus === "Pending" || row.conflictStatus === "Reviewed" || row.conflictStatus === "Resolved") {
      conflictCounts[row.conflictStatus] = Number(row.total || 0);
    }
  }

  const criticalRows = await prisma.$queryRawUnsafe<Array<{ conflictStatus: string; activePlatforms: string | null; currentQuantity: number }>>(
    `SELECT "conflictStatus", "activePlatforms", "currentQuantity" FROM "MarketplaceConflict"`
  );
  const criticalConflicts = criticalRows.filter((row) => {
    if (row.conflictStatus !== "Pending") return false;
    const active = parsePlatforms(row.activePlatforms);
    return active.length > 1 || Number(row.currentQuantity || 0) === 0;
  }).length;

  const coverageSummary: Record<string, number> = {
    "eBayOnly": 0,
    "etsyOnly": 0,
    "amazonOnly": 0,
    "ebayEtsy": 0,
    "ebayAmazon": 0,
    "etsyAmazon": 0,
    "allPlatforms": 0,
  };

  for (const item of filtered) {
    const key = item.platforms.slice().sort().join("+");
    if (key === "EBAY") coverageSummary.eBayOnly += 1;
    else if (key === "ETSY") coverageSummary.etsyOnly += 1;
    else if (key === "AMAZON") coverageSummary.amazonOnly += 1;
    else if (key === "EBAY+ETSY") coverageSummary.ebayEtsy += 1;
    else if (key === "AMAZON+EBAY") coverageSummary.ebayAmazon += 1;
    else if (key === "AMAZON+ETSY") coverageSummary.etsyAmazon += 1;
    else if (key === "AMAZON+EBAY+ETSY") coverageSummary.allPlatforms += 1;
  }

  const recentActivity = await getMarketplaceActivityFeed(10);
  return { totalListings, platformCounts, conflictCounts, criticalConflicts, coverageSummary, recentActivity, rows: filtered };
}

export type MarketplaceAuditMetrics = {
  totalListings: number;
  priceAlerts: number;
  lowMargin: number;
  revenueLeakage: number;
  affectedLeakageCount: number;
  largestLeakage: number;
  largestLeakageSku: string;
  largestLeakageName: string;
  opportunities: number;
  opportunityRevenue: number;
  topOpportunitySku: string;
  topOpportunityName: string;
  topOpportunityValue: number;
  topRiskSku: string;
  topRiskName: string;
  topRiskLeakage: number;
  avgMargin: number;
  greenCount: number;
  amberCount: number;
  redCount: number;
  totalListedValue: number;
  totalProfit: number;
  bestPlatform: string;
  bestPlatformProfit: number;
  bestPlatformMargin: number;
  bestCategory: string;
  bestCategoryProfit: number;
  bestCategoryMargin: number;
  bestSku: string;
  bestSkuName: string;
  bestSkuProfit: number;
  healthScore: number;
  usdRate: number;
};

export async function getMarketplaceAuditMetrics(rates?: CurrencyRates): Promise<MarketplaceAuditMetrics> {
  const rateMap = rates ?? (await getCurrencyRates());
  const rows = await prisma.$queryRawUnsafe<Array<{
    platform: string;
    listingUrl: string;
    listedPrice: number;
    currency: string;
    listedDate: string;
    sellingPrice: number;
    costPrice: number;
    sku: string;
    itemName: string;
    category: string;
  }>>(`
    SELECT l."platform", l."listingUrl", l."listedPrice", COALESCE(l."currency",'USD') AS "currency", l."listedDate",
           i."sellingPrice", i."costPrice", i."sku", i."itemName", i."category"
    FROM "Listing" l
    ${marketplaceInventoryJoinSql("INNER")}
    WHERE ${MARKETPLACE_LISTING_SCOPE_SQL}
  `);

  const items = rows.map((r) => {
    const lp = Number(r.listedPrice) || 0;
    const currency = String(r.currency || "INR");
    let lpInr = toInr(lp, currency, rateMap);
    if (!Number.isFinite(lpInr)) lpInr = lp; // no configured rate: fall back to raw value
    const sp = Number(r.sellingPrice) || 0;
    const cp = Number(r.costPrice) || 0;
    const profit = lpInr - cp;
    const margin = cp > 0 ? (profit / cp) * 100 : 0;
    const leakage = lpInr < sp ? sp - lpInr : 0;
    const isOpportunity = lpInr > sp * 1.5;
    const oppRevenue = isOpportunity ? lpInr - sp : 0;
    return { ...r, lpInr, sp, cp, profit, margin, leakage, isOpportunity, oppRevenue };
  });

  const total = items.length;
  const priceAlerts = items.filter((i) => i.lpInr < i.sp).length;
  const lowMargin = items.filter((i) => i.margin < 100).length;
  const red = items.filter((i) => i.margin < 100).length;
  const amber = items.filter((i) => i.margin >= 100 && i.margin < 300).length;
  const green = items.filter((i) => i.margin >= 300).length;
  const totalLeakage = items.reduce((s, i) => s + i.leakage, 0);
  const leakageItems = items.filter((i) => i.leakage > 0);
  const largest = leakageItems.sort((a, b) => b.leakage - a.leakage)[0];
  const totalProfit = items.reduce((s, i) => s + i.profit, 0);
  const totalListed = items.reduce((s, i) => s + i.lpInr, 0);
  const avgMargin = total > 0 ? items.reduce((s, i) => s + i.margin, 0) / total : 0;
  const opportunities = items.filter((i) => i.isOpportunity).length;
  const oppRevenue = items.reduce((s, i) => s + i.oppRevenue, 0);
  const topOpp = items.filter((i) => i.isOpportunity).sort((a, b) => b.oppRevenue - a.oppRevenue)[0];

  // Platform pivot
  const mpMap = new Map<string, { profit: number; margin: number; count: number }>();
  for (const i of items) {
    const k = i.platform || "Unknown";
    const e = mpMap.get(k) || { profit: 0, margin: 0, count: 0 };
    e.profit += i.profit; e.margin += i.margin; e.count++;
    mpMap.set(k, e);
  }
  const bestMp = Array.from(mpMap.entries()).sort((a, b) => b[1].profit - a[1].profit)[0];

  // Category pivot
  const catMap = new Map<string, { profit: number; margin: number }>();
  for (const i of items) {
    const k = i.category || "Unknown";
    const e = catMap.get(k) || { profit: 0, margin: 0 };
    e.profit += i.profit; e.margin += i.margin;
    catMap.set(k, e);
  }
  const bestCat = Array.from(catMap.entries()).sort((a, b) => b[1].profit - a[1].profit)[0];

  const bestSku = [...items].sort((a, b) => b.profit - a.profit)[0];

  // Health Score
  const priceCompliance = total > 0 ? Math.max(0, (total - priceAlerts) / total * 40) : 40;
  const marginHealth = total > 0 ? Math.max(0, green / total * 30) : 30;
  const coverage = 20;
  const healthScore = Math.round(Math.min(100, priceCompliance + marginHealth + coverage));

  return {
    totalListings: total,
    priceAlerts, lowMargin,
    revenueLeakage: Math.round(totalLeakage),
    affectedLeakageCount: leakageItems.length,
    largestLeakage: Math.round(largest?.leakage || 0),
    largestLeakageSku: largest?.sku || "",
    largestLeakageName: largest?.itemName || "",
    opportunities,
    opportunityRevenue: Math.round(oppRevenue),
    topOpportunitySku: topOpp?.sku || "",
    topOpportunityName: topOpp?.itemName || "",
    topOpportunityValue: Math.round(topOpp?.oppRevenue || 0),
    topRiskSku: largest?.sku || "",
    topRiskName: largest?.itemName || "",
    topRiskLeakage: Math.round(largest?.leakage || 0),
    avgMargin: Math.round(avgMargin * 10) / 10,
    greenCount: green, amberCount: amber, redCount: red,
    totalListedValue: Math.round(totalListed),
    totalProfit: Math.round(totalProfit),
    bestPlatform: bestMp?.[0] || "—",
    bestPlatformProfit: Math.round(bestMp?.[1].profit || 0),
    bestPlatformMargin: Math.round(bestMp ? bestMp[1].margin / bestMp[1].count * 10 : 0) / 10,
    bestCategory: bestCat?.[0] || "—",
    bestCategoryProfit: Math.round(bestCat?.[1].profit || 0),
    bestCategoryMargin: Math.round(bestCat ? bestCat[1].margin / items.filter(i => (i.category || "Unknown") === (bestCat[0] || "Unknown")).length * 10 : 0) / 10,
    bestSku: bestSku?.sku || "",
    bestSkuName: bestSku?.itemName || "",
    bestSkuProfit: Math.round(bestSku?.profit || 0),
    healthScore,
    usdRate: Number(rateMap.USD) || 0,
  };
}
